using System;using System.Drawing;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms { public class FrmAdmissionList:StyledForm {
 DataGridView g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};TextBox seat=new TextBox(),name=new TextBox(),university=new TextBox(),year=new TextBox();CheckBox eligible=new CheckBox{Text="Eligible",Checked=true,AutoSize=true};int id;
 public FrmAdmissionList(){Text="Admission List";Size=new Size(1050,650);Controls.Add(g);var editor=new TableLayoutPanel{Dock=DockStyle.Right,Width=300,Padding=new Padding(18),ColumnCount=1,AutoScroll=true};editor.Controls.Add(new Label{Text="Admission Record",Font=new Font("Segoe UI",15,FontStyle.Bold),AutoSize=true});Add(editor,"Seat number",seat);Add(editor,"Student name",name);Add(editor,"University",university);Add(editor,"Academic year",year);editor.Controls.Add(eligible);var save=new Button{Text="Save Record",Width=150,Height=38};var clear=UiTheme.Secondary("New / Clear");var del=UiTheme.Secondary("Delete");editor.Controls.Add(save);editor.Controls.Add(clear);editor.Controls.Add(del);Controls.Add(editor);Controls.Add(UiTheme.Heading("Admission List","Manage fictional UCS Pyay eligibility records"));g.SelectionChanged+=delegate{LoadSelected();};clear.Click+=delegate{Clear();};save.Click+=delegate{try{new AdmissionQuery().Save(id,seat.Text.Trim(),name.Text.Trim(),university.Text.Trim(),year.Text.Trim(),eligible.Checked);LoadData();Clear();}catch(Exception ex){MessageBox.Show(ex.Message,"Unable to save");}};del.Click+=delegate{if(id>0&&MessageBox.Show("Delete this admission record?","Confirm",MessageBoxButtons.YesNo)==DialogResult.Yes){new AdmissionQuery().Delete(id);LoadData();Clear();}};Clear();LoadData();}
 void Add(TableLayoutPanel p,string label,Control c){p.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(3,10,3,2)});c.Width=245;p.Controls.Add(c);}void LoadData(){g.DataSource=new AdmissionQuery().All();if(g.Columns.Contains("AdmissionId"))g.Columns["AdmissionId"].Visible=false;}void LoadSelected(){if(g.CurrentRow==null||g.CurrentRow.IsNewRow||g.CurrentRow.Cells["AdmissionId"].Value==null||g.CurrentRow.Cells["AdmissionId"].Value==DBNull.Value)return;id=Convert.ToInt32(g.CurrentRow.Cells["AdmissionId"].Value);seat.Text=Convert.ToString(g.CurrentRow.Cells["SeatNumber"].Value);name.Text=Convert.ToString(g.CurrentRow.Cells["StudentName"].Value);university.Text=Convert.ToString(g.CurrentRow.Cells["University"].Value);year.Text=Convert.ToString(g.CurrentRow.Cells["AcademicYear"].Value);eligible.Checked=g.CurrentRow.Cells["IsEligible"].Value!=DBNull.Value&&Convert.ToBoolean(g.CurrentRow.Cells["IsEligible"].Value);}void Clear(){id=0;seat.Text=name.Text="";university.Text="University of Computer Studies, Pyay";year.Text=new SystemSettingsQuery().Get("AcademicYear");eligible.Checked=true;}
} }
